# Try to discover the API routes
import httpx

base_url = "http://127.0.0.1:38467/v1"
api_key = "arc-proxy"

print("Trying to discover API routes...")
with httpx.Client(timeout=5) as client:
    # Try OPTIONS to discover routes
    routes = [
        "/", "/health", "/submit", "/tasks", "/execute", "/run", "/eval",
        f"/tasks/{task_id}", f"/submit/{task_id}"
    ]

    for route in routes:
        try:
            # OPTIONS for route discovery
            resp = client.options(f"{base_url}{route}", headers={"Authorization": f"Bearer {api_key}"})
            if resp.status_code == 200:
                print(f"  {route}: OPTIONS={resp.status_code}")
        except:
            pass

        # POST for submission attempts
        for action in ["submit", "run"]:
            try:
                resp = client.post(f"{base_url}{route}", 
                                  headers={
                                      "Authorization": f"Bearer {api_key}",
                                      "Content-Type": "application/json"
                                  },
                                  json={"action": action})
                if resp.status_code in [200, 201, 400, 403]:
                    print(f"  {route}/{action}: {resp.status_code} - {resp.text[:100]}")
            except Exception as e:
                print(f"  {route}/{action}: Error - {e}")

